-- A table for the Grove's pets.
CREATE TABLE pets (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  kind TEXT NOT NULL
);

INSERT INTO pets (name, kind) VALUES
  ('Pip', 'mouse'),
  ('Mossy', 'frog');

SELECT name, kind
FROM pets
ORDER BY name;

-- Grove library loans: who lends a book to
-- whom. Both roles are members, so loans has
-- two foreign keys to the same table.
CREATE TABLE members (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL
);
INSERT INTO members VALUES (1, 'Pip'), (2, 'Mossy');

CREATE TABLE loans (
  id INTEGER PRIMARY KEY,
  lender_id INTEGER NOT NULL REFERENCES members (id),
  borrower_id INTEGER NOT NULL REFERENCES members (id),
  title TEXT NOT NULL,
  CHECK (lender_id <> borrower_id)
);
INSERT INTO loans VALUES (1, 1, 2, 'Pond Tales');

-- One join per role, each with its own alias.
SELECT l.title, f.name AS lender, t.name AS borrower
FROM loans AS l
JOIN members AS f ON f.id = l.lender_id
JOIN members AS t ON t.id = l.borrower_id;

