import { useEffect, useState } from "react";
import StandingsTable from "./StandingsTable.jsx";

// "moon" isn't a real division: it's there to
// see what the page does when the API says no.
const DIVISIONS = ["all", "north", "south", "moon"];

export default function App() {
  const [division, setDivision] = useState("all");
  const [rows, setRows] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    const query =
      division === "all" ? "" : `?division=${division}`;
    setError(null);
    fetch(`/api/standings${query}`)
      .then(async (response) => {
        const data = await response.json();
        if (response.ok) {
          setRows(data);
        } else {
          setError(data.title);
          setRows([]);
        }
      });
  }, [division]);

  return (
    <main>
      <h1>Junior League standings</h1>
      <nav aria-label="Divisions">
        {DIVISIONS.map((d) => (
          <button
            key={d}
            id={`show-${d}`}
            aria-pressed={d === division}
            onClick={() => setDivision(d)}
          >
            {d}
          </button>
        ))}
      </nav>
      {error && (
        <p id="error" role="alert">
          {error}
        </p>
      )}
      {rows === null ? (
        <p>Loading standings…</p>
      ) : (
        <StandingsTable rows={rows} />
      )}
    </main>
  );
}

