import { useState } from "react";

const DAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"];

export default function NewClubForm({ onAdded }) {
  const [name, setName] = useState("");
  const [meets, setMeets] = useState("Monday");
  const [error, setError] = useState("");

  async function handleSubmit(event) {
    event.preventDefault();
    const response = await fetch("/api/clubs", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name, meets }),
    });
    if (response.ok) {
      setName("");
      setError("");
      onAdded();
    } else {
      setError(await response.json());
    }
  }

  return (
    <form id="new-club" onSubmit={handleSubmit}>
      <h2>Start a new club</h2>
      <label htmlFor="club-name">Club name</label>
      <input
        id="club-name"
        value={name}
        onChange={(e) => setName(e.target.value)}
      />
      <label htmlFor="club-day">Meets on</label>
      <select
        id="club-day"
        value={meets}
        onChange={(e) => setMeets(e.target.value)}
      >
        {DAYS.map((day) => (
          <option key={day}>{day}</option>
        ))}
      </select>
      <button type="submit">Start club</button>
      {error && (
        <p id="error" role="alert">
          {error}
        </p>
      )}
    </form>
  );
}

