using Microsoft.EntityFrameworkCore;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<LeagueDb>(
    o => o.UseInMemoryDatabase("league"));
var app = builder.Build();

// Creates the database with its seed rows.
using (var scope = app.Services.CreateScope())
{
    scope.ServiceProvider.GetRequiredService<LeagueDb>()
        .Database.EnsureCreated();
}

// GET /api/standings?division=north (or south).
// Other divisions: 400, with problem details.
app.MapGet("/api/standings", (string division, LeagueDb db) =>
{
    if (division is not null && division is not ("north" or "south"))
        return Results.Problem(
            title: $"There's no {division} division.",
            statusCode: 400);

    var teams = db.Teams
        .Where(t => division == null || t.Division == division)
        .ToList();
    var matches = db.Matches.ToList();
    var table = teams
        .Select(t => new Standing(
            t.Name,
            matches.Count(m => Plays(m, t.Id)),
            matches.Sum(m => Points(m, t.Id))))
        .OrderByDescending(s => s.Points)
        .ThenBy(s => s.Team)
        .ToList();
    return Results.Ok(table);
});

app.MapPost("/api/matches", (NewMatch input, LeagueDb db) =>
{
    var errors = new Dictionary<string, string[]>();
    if (db.Teams.Find(input.HomeTeamId) is null)
        errors["homeTeamId"] = [$"There's no team {input.HomeTeamId}."];
    if (db.Teams.Find(input.AwayTeamId) is null)
        errors["awayTeamId"] = [$"There's no team {input.AwayTeamId}."];
    else if (input.AwayTeamId == input.HomeTeamId)
        errors["awayTeamId"] = ["A team can't play itself."];
    if (input.HomeGoals < 0)
        errors["homeGoals"] = ["Goals can't be below 0."];
    if (input.AwayGoals < 0)
        errors["awayGoals"] = ["Goals can't be below 0."];
    if (errors.Count > 0) return Results.ValidationProblem(errors);

    var match = new Match
    {
        HomeTeamId = input.HomeTeamId,
        AwayTeamId = input.AwayTeamId,
        HomeGoals = input.HomeGoals,
        AwayGoals = input.AwayGoals,
    };
    db.Matches.Add(match);
    db.SaveChanges();
    return Results.Created($"/api/matches/{match.Id}", match);
});

app.MapGet("/api/matches/{id:int}", (int id, LeagueDb db) =>
    db.Matches.Find(id) is { } match
        ? Results.Ok(match)
        : Results.NotFound());

app.MapDelete("/api/matches/{id:int}", (int id, LeagueDb db) =>
{
    if (db.Matches.Find(id) is not { } match) return Results.NotFound();
    db.Matches.Remove(match);
    db.SaveChanges();
    return Results.NoContent();
});

app.Run();

static bool Plays(Match m, int team) =>
    m.HomeTeamId == team || m.AwayTeamId == team;

// 3 points for a win, 1 for a draw.
static int Points(Match m, int team)
{
    if (!Plays(m, team)) return 0;
    var home = m.HomeTeamId == team;
    var mine = home ? m.HomeGoals : m.AwayGoals;
    var theirs = home ? m.AwayGoals : m.HomeGoals;
    return mine > theirs ? 3 : mine == theirs ? 1 : 0;
}

