import { useEffect, useState } from "react";

const EMPTY = {
  homeTeamId: "",
  awayTeamId: "",
  homeGoals: "",
  awayGoals: "",
};

export default function ResultForm({ onRecorded }) {
  const [teams, setTeams] = useState([]);
  const [form, setForm] = useState(EMPTY);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    fetch("/api/teams")
      .then((response) => response.json())
      .then((data) => setTeams(data));
  }, []);

  function update(field, value) {
    setForm({ ...form, [field]: value });
  }

  async function handleSubmit(event) {
    event.preventDefault();
    const response = await fetch("/api/matches", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        homeTeamId: Number(form.homeTeamId),
        awayTeamId: Number(form.awayTeamId),
        homeGoals: Number(form.homeGoals),
        awayGoals: Number(form.awayGoals),
      }),
    });
    if (response.ok) {
      setForm(EMPTY);
      setErrors({});
      onRecorded();
    } else {
      const problem = await response.json();
      setErrors(problem.errors ?? {});
    }
  }

  const teamOptions = [
    <option key="" value="">
      Choose a team
    </option>,
    ...teams.map((t) => (
      <option key={t.id} value={t.id}>
        {t.name}
      </option>
    )),
  ];

  return (
    <form id="result-form" onSubmit={handleSubmit} noValidate>
      <h2>Record a result</h2>
      <Field id="home-team" label="Home team"
        error={errors.homeTeamId?.[0]}>
        {(props) => (
          <select {...props} value={form.homeTeamId}
            onChange={(e) => update("homeTeamId", e.target.value)}>
            {teamOptions}
          </select>
        )}
      </Field>
      <Field id="away-team" label="Away team"
        error={errors.awayTeamId?.[0]}>
        {(props) => (
          <select {...props} value={form.awayTeamId}
            onChange={(e) => update("awayTeamId", e.target.value)}>
            {teamOptions}
          </select>
        )}
      </Field>
      <Field id="home-goals" label="Home goals"
        error={errors.homeGoals?.[0]}>
        {(props) => (
          <input {...props} type="number" value={form.homeGoals}
            onChange={(e) => update("homeGoals", e.target.value)} />
        )}
      </Field>
      <Field id="away-goals" label="Away goals"
        error={errors.awayGoals?.[0]}>
        {(props) => (
          <input {...props} type="number" value={form.awayGoals}
            onChange={(e) => update("awayGoals", e.target.value)} />
        )}
      </Field>
      <button type="submit">Record result</button>
    </form>
  );
}

// A label, its control, and the API's message.
// The control gets aria-invalid and
// aria-describedby, so a screen reader reads
// the message with it.
function Field({ id, label, error, children }) {
  const errorId = `${id}-error`;
  return (
    <div className="field">
      <label htmlFor={id}>{label}</label>
      {children({
        id,
        "aria-invalid": error ? "true" : undefined,
        "aria-describedby": error ? errorId : undefined,
      })}
      {error && (
        <p id={errorId} className="field-error">
          {error}
        </p>
      )}
    </div>
  );
}

