using Microsoft.EntityFrameworkCore;

public static class RecentEndpoints
{
    // GET /api/matches/recent?count=5: the
    // newest results first, with both names.
    public static void MapRecentResults(
        this WebApplication app)
    {
        app.MapGet("/api/matches/recent",
            (int? count, LeagueDb db) =>
        {
            var take = count ?? 5;
            if (take is < 1 or > 20)
            {
                var errors = new Dictionary<string, string[]>
                {
                    ["count"] = ["Ask for 1 to 20 results."],
                };
                return Results.ValidationProblem(errors);
            }

            var recent =
                from m in db.Matches
                join h in db.Teams on m.HomeTeamId equals h.Id
                join a in db.Teams on m.AwayTeamId equals a.Id
                orderby m.Id descending
                select new RecentResult(m.Id, h.Name, a.Name,
                    m.HomeGoals, m.AwayGoals);
            return Results.Ok(recent.Take(take).ToList());
        });
    }
}

